package com.example.springbootjwtcrud.controller;import com.example.springbootjwtcrud.model.ExpensesCategories;import com.example.springbootjwtcrud.service.ExpenseService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController("/expenses")public class ExpensesController {    private final ExpenseService expenseService;    public ExpensesController(ExpenseService expenseService) {        this.expenseService = expenseService;    }    @GetMapping("/totalExpense")    public List<Double> GetTotalExpenses(){        return expenseService.GetAllExpenses();    }    @DeleteMapping("/removeExpense/{amount}")    public String DeleteExpense(@PathVariable("amount") Double amount){        return expenseService.DeleteExpense(amount);    }    @PostMapping("/listExpense/{amount}/{category}")    public String ListExpense(@PathVariable("amount") Double amount, @PathVariable("category") ExpensesCategories expensesCategories){        return expenseService.ListExpense(amount, expensesCategories);    }    @PutMapping("/updateExpense/{amount}/{newAmount}")    public String UpdateExpense(@PathVariable("amount") Double amount, @PathVariable("newAmount") Double newAmount){        return expenseService.UpdateExpensePrice(amount, newAmount);    }}